const slug=name=>COUNTRIES.find(c=>c.name===name)?.id||'3b';
const CANON_GUARDIANS={
 C165:{name:'Céliane — France',value:'Justice'},
 C166:{name:'Alessio — Italie',value:'Espoir'},
 C167:{name:'Eira — Estonie',value:'Sagesse'},
