export function puzzleStart(region){const c=CHAPTERS[region];return [...(c.initial||[])];}
export function puzzleStep(region,board,index){
 const c=CHAPTERS[region];if(!c||!Number.isInteger(index)||index<0||index>8)return board;
 const b=[...board];
 if(c.kind==='sequence'){if(index>3)return b;return b.length>=4?[index]:[...b,index];}
 if(c.kind==='path'){if(c.blocked.includes(index))return b;if(b.at(-1)===index)return b.slice(0,-1);if(!b.length)return index===0?[0]:[];const last=b.at(-1);return !b.includes(index)&&Math.abs(last%3-index%3)+Math.abs(Math.floor(last/3)-Math.floor(index/3))===1?[...b,index]:b;}
 if(index>=b.length)return b;
 if(c.kind==='lights'){for(const i of [index-1,index,index+1])if(i>=0&&i<b.length)b[i]=1-b[i];}
 else {b[index]=(b[index]+1)%4;if(c.kind==='gears'&&index<2)b[index+1]=(b[index+1]+1)%4;}
 return b;
}
export function waterFlow(board){
 const visited=[];let cell=0,input=3;
 for(let i=0;i<4;i++){
  const turn=board[cell],ports=[turn,(turn+1)%4];if(!ports.includes(input)||visited.includes(cell))return{visited,complete:false};visited.push(cell);
  const output=ports.find(p=>p!==input);if(cell===1&&output===1)return{visited,complete:visited.length===4};
  const x=cell%2+[0,1,0,-1][output],y=Math.floor(cell/2)+[-1,0,1,0][output];if(x<0||x>1||y<0||y>1)return{visited,complete:false};cell=y*2+x;input=(output+2)%4;
 }return{visited,complete:false};
}
